ALTER TABLE sender_routes ADD actor_id text;
ALTER TABLE sender_routes ADD FOREIGN KEY(org_id,actor_id) REFERENCES users(org_id,id);
CREATE TABLE reminder_rules (id text PRIMARY KEY, org_id text NOT NULL, branch_id text NOT NULL, actor_id text NOT NULL, name text NOT NULL, days_overdue integer NOT NULL CHECK(days_overdue BETWEEN 0 AND 365), cadence_days integer NOT NULL CHECK(cadence_days BETWEEN 1 AND 90), max_followups integer NOT NULL CHECK(max_followups BETWEEN 1 AND 12), active boolean NOT NULL DEFAULT true, last_run_date date, UNIQUE(org_id,id), FOREIGN KEY(org_id,branch_id) REFERENCES branches(org_id,id), FOREIGN KEY(org_id,actor_id) REFERENCES users(org_id,id));
CREATE TABLE reminder_occurrences (org_id text NOT NULL, rule_id text NOT NULL, invoice_id text NOT NULL, sequence integer NOT NULL CHECK(sequence>0), occurred_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(org_id,rule_id,invoice_id,sequence), FOREIGN KEY(org_id,rule_id) REFERENCES reminder_rules(org_id,id), FOREIGN KEY(org_id,invoice_id) REFERENCES invoices(org_id,id));
